/**
 * Re-publishes every form that currently has a render-cache blob, so the cache is
 * regenerated by the freshly deployed C# plugin (DFE 4-point mirror: designer business
 * rules, scoped-button Arabic translation, multi-column lookup config).
 *
 * Calls the unbound qdb_PublishForm custom API with { FormCode, TargetVersion }.
 * PublishJobId is optional, so no pre-created publish job is needed.
 *
 * Run: node --env-file=scripts/.env scripts/republish-cached-forms.mjs
 */
const T = process.env.DV_TENANT_ID, C = process.env.DV_CLIENT_ID, S = process.env.DV_CLIENT_SECRET, U = process.env.DV_DATAVERSE_URL;
const API = `${U}/api/data/v9.2`;

async function token() {
  const r = await fetch(`https://login.microsoftonline.com/${T}/oauth2/v2.0/token`, {
    method: 'POST', body: new URLSearchParams({ grant_type: 'client_credentials', client_id: C, client_secret: S, scope: `${U}/.default` }),
  });
  const j = await r.json(); if (!r.ok) throw new Error(j.error_description); return j.access_token;
}

async function main() {
  const tok = await token();
  const h = { Authorization: `Bearer ${tok}`, Accept: 'application/json', 'Content-Type': 'application/json', 'OData-MaxVersion': '4.0', 'OData-Version': '4.0' };
  console.log('✓ Token');

  // Distinct form codes that have a cache blob (these are the "affected" forms).
  const cache = (await (await fetch(`${API}/qdb_form_render_caches?$select=qdb_form_code&$top=500`, { headers: h })).json()).value;
  const codes = [...new Set(cache.map(r => r.qdb_form_code).filter(Boolean))];
  console.log(`Cached forms: ${codes.length}`);

  // Resolve each form's current version.
  const defs = (await (await fetch(`${API}/qdb_form_definitions?$select=qdb_form_code,qdb_version&$filter=statecode eq 0`, { headers: h })).json()).value;
  const versionByCode = Object.fromEntries(defs.map(d => [d.qdb_form_code, d.qdb_version ?? 1]));

  let ok = 0, skipped = 0, failed = 0;
  for (const code of codes.sort()) {
    const version = versionByCode[code];
    if (version === undefined) { console.log(`  ↷ ${code} — no active form definition, skipping`); skipped++; continue; }

    // 1. Create the publish-job tracking record (do NOT bind qdb_form_definition_id → 400).
    const jobRes = await fetch(`${API}/qdb_publish_jobs`, {
      method: 'POST', headers: { ...h, Prefer: 'return=representation' },
      body: JSON.stringify({ qdb_form_code: code, qdb_target_version: version, qdb_status: 1, qdb_trigger_reason: 1 }),
    });
    if (!jobRes.ok) { console.log(`  ✗ ${code} (v${version}) → job create ${jobRes.status}: ${(await jobRes.text()).slice(0, 140)}`); failed++; continue; }
    const publishJobId = (await jobRes.json()).qdb_publish_jobid;

    // 2. Invoke the publish action with ONLY these three params (extra params → 400).
    const r = await fetch(`${API}/qdb_PublishForm`, {
      method: 'POST', headers: h,
      body: JSON.stringify({ FormCode: code, TargetVersion: version, PublishJobId: publishJobId }),
    });
    if (r.ok) { console.log(`  ✓ ${code} (v${version}) job=${publishJobId.slice(0, 8)}`); ok++; }
    else { const t = await r.text(); console.log(`  ✗ ${code} (v${version}) → ${r.status}: ${t.slice(0, 160)}`); failed++; }
  }
  console.log(`\n=== Done. Published ${ok}, skipped ${skipped}, failed ${failed}. ===`);
}
main().catch(e => { console.error('\nFAILED:', e.message); process.exit(1); });
